#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1 && tput clear 2>/dev/null; then return 0; fi
  printf '\033[2J\033[3J\033[H'
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else false; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any, with write_env's single
# quotes or a plain dotenv double-quoted value undone.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line value sq="'\\''"; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  value="${line#*=}"
  if [[ "$value" == \'*\' ]]; then value="${value:1:${#value}-2}"; value="${value//"$sq"/\'}"
  elif [[ "$value" == \"*\" ]]; then
    value="${value:1:${#value}-2}"
    [[ "$value" == *[\\\$\"]* ]] && return 1   # escapes, $ or ": can't decode safely; ask again
  fi
  printf '%s' "$value"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret), edited
# with Readline. Fails at EOF with no input.
ask() {
  local key="$1" prompt="$2" current input s=$'\001' e=$'\002' p rc=0
  current=$(_existing "$key" || true)
  # Readline needs the colour codes wrapped in \001..\002 to place the cursor.
  p="  $s$BOLD$e$prompt$s$RESET$e "
  [[ -n "$current" ]] && p+="$s$DIM$e[Enter keeps current]$s$RESET$e "
  read -e -r -p "$p" input || rc=1
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input rc=0
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || rc=1
  printf '\n'
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY='VALUE' into ENV_FILE (replaces any existing
# line) and sets $KEY. Idempotent. Creates ENV_FILE at mode 0600; writes through
# a symlink and keeps an existing file's mode.
write_env() {
  local key="$1" value="$2" tmp sq="'\\''"
  [[ -e "$ENV_FILE" ]] || (umask 077 && : > "$ENV_FILE")
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf "%s='%s'\n" "$key" "${value//\'/$sq}" >> "$tmp"
  cat "$tmp" > "$ENV_FILE"
  rm -f "$tmp"
  printf -v "$key" '%s' "$value"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# Keep every stage inside run_wizard and the last line as is: bash then parses
# the whole file before the first prompt, so an edit mid-run can't break it.
# ──────────────────────────────────────────────────────────────────────────

run_wizard() {

TOTAL_STAGES=5
PROJECT_DIR=$(cd "$(dirname "${BASH_SOURCE[0]}")/.." && pwd)
cd "$PROJECT_DIR"
ENV_FILE="$PROJECT_DIR/.env"
if [[ -x "$PROJECT_DIR/.venv/Scripts/python.exe" ]]; then
  PYTHON_BIN="$PROJECT_DIR/.venv/Scripts/python.exe"
elif command -v python.exe >/dev/null 2>&1; then
  PYTHON_BIN=$(command -v python.exe)
elif command -v python >/dev/null 2>&1; then
  PYTHON_BIN=$(command -v python)
else
  printf 'Python no está disponible. Crea primero el entorno virtual indicado en README.md.\n' >&2
  exit 1
fi

banner "Credenciales de AgroAsistente Chile"

stage "Firebase: proyecto y Realtime Database"
say "Crea un proyecto nuevo para no reutilizar las credenciales comprometidas."
open_url "https://console.firebase.google.com/"
step "Pulsa Crear un proyecto, asigna un nombre y completa el asistente. Analytics es opcional."
step "Dentro del proyecto abre Compilación/Build → Realtime Database → Crear base de datos."
step "Elige una ubicación cercana y comienza en modo bloqueado."
step "Copia la URL completa visible en la parte superior de Realtime Database."
ask FIREBASE_DATABASE_URL "Pega FIREBASE_DATABASE_URL (https://...):"
if [[ ! "$FIREBASE_DATABASE_URL" =~ ^https://.+\.(firebaseio\.com|firebasedatabase\.app)/?$ ]]; then
  warn "La URL no tiene el formato habitual de Realtime Database; revísala antes de continuar."
  confirm "¿Continuar con esta URL?" || exit 1
fi
write_env FIREBASE_DATABASE_URL "$FIREBASE_DATABASE_URL"

stage "Firebase: cuenta de servicio nueva"
say "El JSON contiene una clave privada. No lo pegues en el chat ni lo subas a Git."
open_url "https://console.firebase.google.com/"
step "Abre tu proyecto → engranaje → Configuración del proyecto → Cuentas de servicio."
step "En Firebase Admin SDK pulsa Generar nueva clave privada y confirma Generar clave."
step "El archivo final quedará como credentials/firebase-admin.json y será ignorado por Git."
ask FIREBASE_JSON_SOURCE "Pega la ruta del JSON nuevo descargado:"
if ! "$PYTHON_BIN" -c 'import json,sys; from pathlib import Path; p=Path(sys.argv[1]); d=json.loads(p.read_text(encoding="utf-8")); assert d.get("type")=="service_account" and d.get("private_key") and d.get("project_id")' "$FIREBASE_JSON_SOURCE" 2>/dev/null; then
  warn "No se pudo validar un JSON de cuenta de servicio en esa ruta."
  exit 1
fi
mkdir -p "$PROJECT_DIR/credentials"
cp "$FIREBASE_JSON_SOURCE" "$PROJECT_DIR/credentials/firebase-admin.json"
write_env FIREBASE_CREDENTIALS_PATH "credentials/firebase-admin.json"

stage "Gemini: clave nueva de Google AI Studio"
say "Crea una clave nueva. Las claves nuevas de AI Studio son claves de autorización restringidas a Gemini."
open_url "https://aistudio.google.com/apikey"
step "Si el proyecto no aparece, abre Dashboard → Projects → Import projects e importa el proyecto nuevo."
step "En API Keys pulsa Create API key y selecciona el proyecto nuevo."
step "Copia la clave una sola vez. No reutilices la clave incluida en el RAR anterior."
ask_secret GEMINI_API_KEY "Pega GEMINI_API_KEY (entrada oculta):"
[[ ${#GEMINI_API_KEY} -ge 20 ]] || { warn "La clave parece demasiado corta."; exit 1; }
write_env GEMINI_API_KEY "$GEMINI_API_KEY"

stage "Django: secreto y opciones locales"
DJANGO_SECRET_KEY=$($PYTHON_BIN -c 'from django.core.management.utils import get_random_secret_key; print(get_random_secret_key())')
write_env DJANGO_SECRET_KEY "$DJANGO_SECRET_KEY"
ask GEMINI_MODEL "Modelo de Gemini [recomendado: gemini-3.5-flash-lite]:"
GEMINI_MODEL=${GEMINI_MODEL:-gemini-3.5-flash-lite}
ask AI_DAILY_LIMIT "Límite global diario [recomendado: 20]:"
AI_DAILY_LIMIT=${AI_DAILY_LIMIT:-20}
[[ "$AI_DAILY_LIMIT" =~ ^[1-9][0-9]*$ ]] || { warn "AI_DAILY_LIMIT debe ser un entero positivo."; exit 1; }
write_env GEMINI_MODEL "$GEMINI_MODEL"
write_env AI_DAILY_LIMIT "$AI_DAILY_LIMIT"
write_env DJANGO_DEBUG "True"
write_env DJANGO_ALLOWED_HOSTS "localhost,127.0.0.1"
note "Se generó DJANGO_SECRET_KEY localmente; nunca se mostró en pantalla."

stage "Verificación real de las integraciones"
say "Se ejecutarán Django check, una lectura de Firebase, una consulta breve a Gemini y una consulta a Open-Meteo."
confirm "¿Ejecutar ahora estas pruebas de red?" || { SKIPPED+=("Verificación real de Firebase, Gemini y Open-Meteo"); finish; return; }
"$PYTHON_BIN" manage.py check
"$PYTHON_BIN" manage.py shell -c "from agro.services.firebase_service import _ref; _ref('.info/connected').get(); print('Firebase: credencial aceptada')"
"$PYTHON_BIN" manage.py shell -c "from agro.services.orientation_provider import AdaptadorGemini; c={'region_nombre':'Maule','predio':'Prueba de configuración','modo':'Agrícola','cultivo_nombre':'Trigo','superficie_m2':'100'}; r=AdaptadorGemini().responder(c,'Entrega una recomendación general de observación del cultivo.'); assert r.texto; print('Gemini: respuesta recibida')"
"$PYTHON_BIN" manage.py shell -c "from agro.services.weather_service import obtener_pronostico; p=obtener_pronostico('maule'); assert p['dias']; print('Open-Meteo: pronóstico recibido')"
note "Las tres integraciones respondieron sin imprimir credenciales."

finish
}

run_wizard "$@"; exit
